import { type ModuleLibrary } from '@divi/types';
/**
 * Register Module.
 *
 * Registers a new module provided a module metadata and an object defining its
 * configurations. Once registered, the module is made available in Visual Builder.
 *
 * @since ??
 *
 * @param {object} metadata Module metadata.
 * @param {string} metadata.name Module name.
 * @param {string} metadata.title Module title (singular).
 * @param {string} metadata.titles Module titles (plural).
 * @param {string} metadata.moduleIcon Module icon, used in the "Add Module" modal.
 * @param {string} metadata.category Module category. Used to group modules in the "Add Module" modal.
 * @param {string} [metadata.folder] Optional Module folder.
 * @param {object} [metadata.videos] Optional collection of Help Center videos for the module.
 * @param {string} metadata.videos.id Module video id.
 * @param {string} metadata.videos.name Module video name.
 * @param {object} metadata.attributes Module attributes.
 * @param {object} [metadata.attributes.module] Optional module attribute.
 * @param {object} [metadata.attributes.module.default] Optional module default attribute.
 * @param {object} [metadata.attributes.module.defaultPrintedStyle] Optional module default printed style attribute.
 * @param {object} [metadata.attributes.module.defaultSettings] Optional module default settings attribute.
 * @param {object} [metadata.attributes.module.styleProps] Optional module style props.
 * @param {string} [metadata.d4Shortcode] Optional Divi 4 shortcode. Used for conversion.
 * @param {object} config Module configurations, e.g., Settings, Renderers.
 * @param {object} [config.settings] Module settings.
 * @param {object} config.renderers Module renderers. Used to render module in Visual Builder.
 * @param {object} [config.conversionOutline] Outline of module conversion from Divi 4 to Divi 5.
 * @param {boolean} [config.supportChildObjects] Whether module supports child objects.
 * @param {object} [config.template] Module template.
 * @param {object} [config.placeholderContent] Module placeholder content.
 * @param {string[]} [config.parentsName] Module parent name(s).
 * @param {string[]} [config.childrenName] Module children name(s).
 *
 * @returns {void}
 *
 * @example Basic usage.
 * ```tsx
 * registerModule(metadata, config);
 * ```
 *
 * @example with metadata and config example.
 * ```tsx
 * const metadata =
 * {
 *   "name": "d5-tut/simple-quick-module",
 *   "d4Shortcode": "d5_tut_simple_quick_module",
 *   "title": "Simple Quick Module",
 *   "titles": "Simple Quick Modules",
 *   "category": "module",
 *   "attributes": {
 *     "module": {
 *       "type": "object",
 *       "selector": "{{selector}}",
 *       "default": {
 *         "meta": {
 *           "adminLabel": {
 *             "desktop": {
 *               "value": "Simple Quick Module"
 *             }
 *           }
 *         }
 *       }
 *     },
 *     "title": {
 *       "type": "object",
 *       "selector": "{{selector}} .d5_tut_simple_quick_module_title",
 *       "attributes": {
 *         "class": "d5_tut_simple_quick_module_title"
 *       },
 *       "tagName": "h2",
 *       "inlineEditor": "plainText",
 *       "elementType": "heading",
 *       "childrenSanitizer": "et_core_esc_previously"
 *     },
 *     "content": {
 *       "type": "object",
 *       "selector": "{{selector}} .d5_tut_simple_quick_module_content",
 *       "attributes": {
 *         "class": "d5_tut_simple_quick_module_content"
 *       },
 *       "tagName": "div",
 *       "inlineEditor": "richText",
 *       "childrenSanitizer": "et_core_esc_previously",
 *       "allowHtml": true
 *     }
 *   }
 * };
 *
 * const config = {
 *   // React Function Component for rendering module's output on layout area.
 *   renderers: {
 *     edit: null,
 *   },
 *   settings: {
 *     // React function component that renders module settings' content panel.
 *     content: ({ defaultSettingsAttrs }) => (
 *       <React.Fragment>
 *         <div>Content ...</div>
 *       </React.Fragment>
 *     ),
 *     // React function component that renders module settings' design panel.
 *     design: () => (
 *       <React.Fragment>
 *         <div>Content ...</div>
 *       </React.Fragment>
 *     ),
 *     // React function component that renders module settings' advanced panel.
 *     advanced: () => (
 *       <React.Fragment>
 *         <div>Content ...</div>
 *       </React.Fragment>
 *     ),
 *   },
 *   placeholderContent: {
 *     module: {
 *       decoration: {
 *         background: {
 *           desktop: {
 *             value: {
 *               color: '#DFDFDF',
 *             }
 *           }
 *         },
 *       }
 *     },
 *     title: {
 *       innerContent: {
 *         desktop: {
 *           value: 'Module Title'
 *         }
 *       }
 *     },
 *     content: {
 *       innerContent: {
 *         desktop: {
 *           value: 'Module Content'
 *         }
 *       }
 *     }
 *   },
 * };
 *
 *  // call registerModule
 * addAction('divi.moduleLibrary.registerModuleLibraryStore.after', 'd5Example.simpleQuickModule', () => {
 *   registerModule(metadata, config);
 * });
 * ```
 */
export declare const registerModule: (metadata: ModuleLibrary.Module.RegisterDefinition['metadata'], config: Omit<ModuleLibrary.Module.RegisterDefinition, 'metadata'>) => void;
